TEMP = r"В полдень %s в Ростове было $%s^{\circ}$C, а в Воронеже $%s^{\circ}$C. Сравните эти температуры."
def tcmp(date, a, b, key, ww=None):
    A, Bv = src(a), src(b)
    s = {">": r"$%s>%s$" % (A, Bv), "<": r"$%s<%s$" % (A, Bv), "=": r"$%s=%s$" % (A, Bv)}
    w = {">": r"Ученик ошибся в сравнении: из двух отрицательных чисел больше то, у которого модуль меньше.", "<": r"Ученик сравнил модули, а не сами числа.", "=": r"Ученик решил, что температуры равны; числа различны."}
    w.update(ww or {})
    return P(TEMP % (date, A, Bv), s[key], [(s[x], w[x]) for x in (">", "<", "=") if x != key], yn=True)
